 * @cipherbox/core - File Metadata Encryption
 *
 * Encrypts and decrypts per-file metadata using AES-256-GCM.
 * File metadata is encrypted with the parent folder's folderKey
 * (NOT the file's own encryption key).
 */

import {
  encryptAesGcm,
  decryptAesGcm,
  generateIv,
  bytesToHex,
  hexToBytes,
  CryptoError,
} from '@cipherbox/crypto';
import type { FileMetadata, EncryptedFileMetadata, VersionEntry } from './types';

/**
 * [SECURITY: MEDIUM-08] Chunk-based base64 encoding to avoid call stack issues
 * with large Uint8Arrays (spread operator has argument limits ~65536)
 */
function uint8ArrayToBase64(bytes: Uint8Array): string {
  const CHUNK_SIZE = 32768;
  let result = '';
  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
    const chunk = bytes.subarray(i, Math.min(i + CHUNK_SIZE, bytes.length));
    result += String.fromCharCode(...chunk);
  }
  return btoa(result);
}

/**
 * Validates a single version entry from the versions array.
 * All fields are required (versions always have explicit encryption mode).
 */
function validateVersionEntry(entry: unknown, index: number): VersionEntry {
  if (typeof entry !== 'object' || entry === null) {
    throw new CryptoError(
      `Invalid file metadata format: versions[${index}] is not an object`,
      'DECRYPTION_FAILED'
    );
  }

  const obj = entry as Record<string, unknown>;

  if (typeof obj.cid !== 'string') {
    throw new CryptoError(
      `Invalid file metadata format: versions[${index}].cid must be string`,
      'DECRYPTION_FAILED'
    );
  }
  if (typeof obj.fileKeyEncrypted !== 'string') {
    throw new CryptoError(
      `Invalid file metadata format: versions[${index}].fileKeyEncrypted must be string`,
      'DECRYPTION_FAILED'
    );
  }
  if (typeof obj.fileIv !== 'string') {
    throw new CryptoError(
      `Invalid file metadata format: versions[${index}].fileIv must be string`,
      'DECRYPTION_FAILED'
    );
  }
  if (typeof obj.size !== 'number') {
    throw new CryptoError(
      `Invalid file metadata format: versions[${index}].size must be number`,
      'DECRYPTION_FAILED'
    );
  }
  if (typeof obj.timestamp !== 'number') {
    throw new CryptoError(
      `Invalid file metadata format: versions[${index}].timestamp must be number`,
      'DECRYPTION_FAILED'
    );
  }
  if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
    throw new CryptoError(
      `Invalid file metadata format: versions[${index}].encryptionMode must be GCM or CTR`,
      'DECRYPTION_FAILED'
    );
  }

  return {
    cid: obj.cid as string,
    fileKeyEncrypted: obj.fileKeyEncrypted as string,
    fileIv: obj.fileIv as string,
    size: obj.size as number,
    timestamp: obj.timestamp as number,
    encryptionMode: obj.encryptionMode as 'GCM' | 'CTR',
  };
}

/**
 * [SECURITY: MEDIUM-07] Runtime validation for decrypted file metadata.
 * Ensures the decrypted data conforms to the expected FileMetadata schema.
 */
export function validateFileMetadata(data: unknown): FileMetadata {
  if (typeof data !== 'object' || data === null) {
    throw new CryptoError('Invalid file metadata format: not an object', 'DECRYPTION_FAILED');
  }

  const obj = data as Record<string, unknown>;

  // Validate version field
  if (obj.version !== 'v1') {
    throw new CryptoError('Invalid file metadata format: unsupported version', 'DECRYPTION_FAILED');
  }

  // Validate required string fields
  if (typeof obj.cid !== 'string') {
    throw new CryptoError('Invalid file metadata format: cid must be string', 'DECRYPTION_FAILED');
  }
  if (typeof obj.fileKeyEncrypted !== 'string') {
    throw new CryptoError(
      'Invalid file metadata format: fileKeyEncrypted must be string',
      'DECRYPTION_FAILED'
    );
  }
  if (typeof obj.fileIv !== 'string') {
    throw new CryptoError(
      'Invalid file metadata format: fileIv must be string',
      'DECRYPTION_FAILED'
    );
  }
  if (typeof obj.mimeType !== 'string') {
    throw new CryptoError(
      'Invalid file metadata format: mimeType must be string',
      'DECRYPTION_FAILED'
    );
  }

  // Validate required number fields
  if (typeof obj.size !== 'number') {
    throw new CryptoError('Invalid file metadata format: size must be number', 'DECRYPTION_FAILED');
  }
  if (typeof obj.createdAt !== 'number') {
    throw new CryptoError(
      'Invalid file metadata format: createdAt must be number',
      'DECRYPTION_FAILED'
    );
  }
  if (typeof obj.modifiedAt !== 'number') {
    throw new CryptoError(
      'Invalid file metadata format: modifiedAt must be number',
      'DECRYPTION_FAILED'
    );
  }

  // Validate optional encryptionMode: if present must be 'GCM' or 'CTR'; if absent default to 'GCM'
  if (obj.encryptionMode !== undefined) {
    if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
      throw new CryptoError(
        'Invalid file metadata format: encryptionMode must be GCM or CTR',
        'DECRYPTION_FAILED'
      );
    }
  }

  // Validate optional versions array
  let validatedVersions: VersionEntry[] | undefined;
  if (obj.versions !== undefined) {
    if (!Array.isArray(obj.versions)) {
      throw new CryptoError(
        'Invalid file metadata format: versions must be an array',
        'DECRYPTION_FAILED'
      );
    }
    if (obj.versions.length > 0) {
      validatedVersions = obj.versions.map((entry: unknown, i: number) =>
        validateVersionEntry(entry, i)
      );
    }
  }

  const result: FileMetadata = {
    version: 'v1',
    cid: obj.cid as string,
    fileKeyEncrypted: obj.fileKeyEncrypted as string,
    fileIv: obj.fileIv as string,
    size: obj.size as number,
    mimeType: obj.mimeType as string,
    encryptionMode: (obj.encryptionMode as 'GCM' | 'CTR' | undefined) ?? 'GCM',
    createdAt: obj.createdAt as number,
    modifiedAt: obj.modifiedAt as number,
  };

  if (validatedVersions) {
    result.versions = validatedVersions;
  }

  return result;
}

/**
 * Encrypts file metadata with AES-256-GCM using the parent folder's key.
 *
 * @param metadata - Plaintext file metadata object
 * @param folderKey - 32-byte AES key of the parent folder
 * @returns Encrypted metadata with IV (hex) and ciphertext (base64)
 */
export async function encryptFileMetadata(
  metadata: FileMetadata,
  folderKey: Uint8Array
): Promise<EncryptedFileMetadata> {
  // Generate random IV for this encryption
  const iv = generateIv();

  // Serialize metadata to JSON bytes
  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));

  // Encrypt with AES-256-GCM
  const ciphertext = await encryptAesGcm(plaintext, folderKey, iv);

  // Encode for storage
  // [SECURITY: MEDIUM-08] Use chunked base64 encoding for large metadata
  return {
    iv: bytesToHex(iv),
    data: uint8ArrayToBase64(ciphertext),
  };
}

/**
 * Decrypts file metadata encrypted with AES-256-GCM.
 *
 * @param encrypted - Encrypted metadata with IV (hex) and ciphertext (base64)
 * @param folderKey - 32-byte AES key of the parent folder
 * @returns Decrypted file metadata object
 * @throws CryptoError if decryption fails (wrong key, corrupted data, etc.)
 */
export async function decryptFileMetadata(
  encrypted: EncryptedFileMetadata,
  folderKey: Uint8Array
): Promise<FileMetadata> {
  // Decode IV and ciphertext
  const iv = hexToBytes(encrypted.iv);
  const ciphertext = Uint8Array.from(atob(encrypted.data), (c) => c.charCodeAt(0));

  // Decrypt with AES-256-GCM
  const plaintext = await decryptAesGcm(ciphertext, folderKey, iv);

  // Parse JSON back to metadata object
  // [SECURITY: MEDIUM-07] Validate the decrypted data before returning
  let parsed: unknown;
  try {
    parsed = JSON.parse(new TextDecoder().decode(plaintext));
  } catch {
    throw new CryptoError('Invalid file metadata format: not valid JSON', 'DECRYPTION_FAILED');
  }
  return validateFileMetadata(parsed);
}
","/**
 * @cipherbox/core - Device Registry Schema Validation
 *
 * Runtime validation for DeviceRegistry JSON after decryption.
 * Uses manual checks consistent with existing codebase patterns
 * (see folder/metadata.ts validateFolderMetadata).
 *
 * Supports v1 -> v2 migration:
 * - v1 registries with empty ipHash are accepted and migrated to v2 with zero placeholder
 * - v2 registries are validated strictly (ipHash must be valid 64-char hex)
 */

import { CryptoError } from '@cipherbox/crypto';
import type { DeviceRegistry, DeviceAuthStatus, DevicePlatform, DeviceEntry } from './types';

const VALID_STATUSES: DeviceAuthStatus[] = ['pending', 'authorized', 'revoked'];
const VALID_PLATFORMS: DevicePlatform[] = ['web', 'macos', 'linux', 'windows'];
const HEX_REGEX = /^[0-9a-fA-F]+$/;

/**
 * Validate a parsed JSON object as a DeviceRegistry.
 *
 * Handles both v1 and v2 formats:
 * - v1: Migrated to v2 (lenient ipHash validation, fills zero placeholder)
 * - v2: Strict validation (ipHash must be valid 64-char hex)
 *
 * Throws CryptoError with code 'DECRYPTION_FAILED' on validation failure
 * to avoid leaking schema details to attackers.
 *
 * @param data - Unknown parsed JSON data
 * @returns Validated DeviceRegistry (always v2)
 * @throws CryptoError if validation fails
 */
export function validateDeviceRegistry(data: unknown): DeviceRegistry {
  if (typeof data !== 'object' || data === null) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }

  const obj = data as Record<string, unknown>;
  const version = obj.version;

  if (version === 'v1') {
    return migrateV1ToV2(obj);
  }
  if (version === 'v2') {
    return validateV2Registry(obj);
  }
  throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
}

/** Validate sequenceNumber and devices array structure (shared by v1 migration and v2 validation). */
function validateRegistryShape(obj: Record<string, unknown>): void {
  if (
    typeof obj.sequenceNumber !== 'number' ||
    !Number.isInteger(obj.sequenceNumber) ||
    obj.sequenceNumber < 0
  ) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }
  if (!Array.isArray(obj.devices)) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }
}

/**
 * Migrate a v1 registry to v2 format.
 *
 * Lenient on ipHash: accepts empty strings from v1 (known bug in useAuth.ts)
 * and fills them with a 64-char zero placeholder.
 */
function migrateV1ToV2(obj: Record<string, unknown>): DeviceRegistry {
  validateRegistryShape(obj);

  const devices = (obj.devices as Record<string, unknown>[]).map((d) => {
    validateDeviceEntryBase(d);
    const ipHash = d.ipHash as string;
    // Only auto-heal the known legacy empty-string bug; reject other malformed values
    if (ipHash !== '' && (ipHash.length !== 64 || !HEX_REGEX.test(ipHash))) {
      throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
    }
    return {
      ...(d as unknown as DeviceEntry),
      ipHash: ipHash === '' ? '0'.repeat(64) : ipHash,
    };
  }) as DeviceEntry[];

  return {
    version: 'v2',
    sequenceNumber: obj.sequenceNumber as number,
    devices,
  };
}

/**
 * Validate a v2 registry with strict validation.
 */
function validateV2Registry(obj: Record<string, unknown>): DeviceRegistry {
  validateRegistryShape(obj);

  for (const device of obj.devices as unknown[]) {
    validateDeviceEntry(device);
  }

  return obj as unknown as DeviceRegistry;
}

/**
 * Validate device entry base fields (everything EXCEPT ipHash length/hex).
 * Used by v1 migration where ipHash may be empty.
 */
function validateDeviceEntryBase(data: unknown): void {
  if (typeof data !== 'object' || data === null) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }

  const entry = data as Record<string, unknown>;

  // Required string fields
  const requiredStrings = [
    'deviceId',
    'publicKey',
    'name',
    'platform',
    'appVersion',
    'deviceModel',
    'ipHash',
    'status',
  ];
  for (const field of requiredStrings) {
    if (typeof entry[field] !== 'string') {
      throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
    }
  }

  // Hex format + length validation for cryptographic fields (except ipHash -- handled by caller)
  const deviceId = entry.deviceId as string;
  if (deviceId.length !== 64 || !HEX_REGEX.test(deviceId)) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }

  const publicKey = entry.publicKey as string;
  if (publicKey.length !== 64 || !HEX_REGEX.test(publicKey)) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }

  // Max length for free-text fields
  if ((entry.name as string).length > 200) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }
  if ((entry.appVersion as string).length > 50) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }
  if ((entry.deviceModel as string).length > 200) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }

  // Validate status is a known value
  if (!VALID_STATUSES.includes(entry.status as DeviceAuthStatus)) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }

  // Validate platform is a known value
  if (!VALID_PLATFORMS.includes(entry.platform as DevicePlatform)) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }

  // Validate timestamp fields
  if (typeof entry.createdAt !== 'number' || typeof entry.lastSeenAt !== 'number') {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }

  // Validate nullable fields
  if (entry.revokedAt !== null && typeof entry.revokedAt !== 'number') {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }
  if (entry.revokedBy !== null && typeof entry.revokedBy !== 'string') {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }
}

/**
 * Validate an individual device entry with strict ipHash validation.
 * Used for v2 registries where ipHash must be a valid 64-char hex string.
 */
function validateDeviceEntry(data: unknown): void {
  validateDeviceEntryBase(data);
  const entry = data as Record<string, unknown>;
  const ipHash = entry.ipHash as string;
  if (ipHash.length !== 64 || !HEX_REGEX.test(ipHash)) {
    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
  }
}
","/**
 * @cipherbox/core - Device Registry Encryption
 *
 * ECIES encryption/decryption for the device registry blob.
 * Uses the same wrapKey/unwrapKey primitives as folder key wrapping.
 *
 * Note: wrapKey/unwrapKey handle arbitrary-length data (not just 32-byte keys).
 * eciesjs internally uses AES-256-GCM for the symmetric portion, so any
 * length payload works. Overhead is ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag).
 * A 10KB registry produces ~10.1KB ciphertext.
 */

import { wrapKey, unwrapKey, CryptoError, clearBytes } from '@cipherbox/crypto';
import { validateDeviceRegistry } from './schema';
import type { DeviceRegistry } from './types';

/**
 * Encrypt the device registry for IPFS storage.
 *
 * Serializes the registry to JSON and encrypts with ECIES using
 * the user's secp256k1 publicKey. Only the holder of the corresponding
 * privateKey can decrypt it.
 *
 * @param registry - The device registry to encrypt
 * @param userPublicKey - 65-byte uncompressed secp256k1 public key
 * @returns Encrypted registry blob
 */
export async function encryptRegistry(
  registry: DeviceRegistry,
  userPublicKey: Uint8Array
): Promise<Uint8Array> {
  const plaintext = new TextEncoder().encode(JSON.stringify(registry));
  try {
    return await wrapKey(plaintext, userPublicKey);
  } finally {
    clearBytes(plaintext);
  }
}

/**
 * Decrypt the device registry from IPFS storage.
 *
 * Decrypts with ECIES using the user's secp256k1 privateKey,
 * parses the JSON, and validates the schema.
 *
 * @param encrypted - ECIES-encrypted registry blob from IPFS
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Validated DeviceRegistry
 * @throws CryptoError if decryption or validation fails
 */
export async function decryptRegistry(
  encrypted: Uint8Array,
  userPrivateKey: Uint8Array
): Promise<DeviceRegistry> {
  const plaintext = await unwrapKey(encrypted, userPrivateKey);
  try {
    const json = new TextDecoder().decode(plaintext);
    const parsed = JSON.parse(json);
    return validateDeviceRegistry(parsed);
  } catch (error) {
    if (error instanceof CryptoError) throw error;
    throw new CryptoError('Registry decryption produced invalid data', 'DECRYPTION_FAILED');
  } finally {
    clearBytes(plaintext);
  }
}
","/**
 * @cipherbox/core - Registry IPNS Key Derivation
 *
 * Derives a deterministic Ed25519 IPNS keypair for the device registry
 * from the user's secp256k1 privateKey using HKDF-SHA256.
 *
 * Derivation path:
 *   secp256k1 privateKey (32 bytes)
 *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-device-registry-ipns-v1")
 *     -> 32-byte Ed25519 seed
 *     -> Ed25519 keypair
 *     -> IPNS name (k51...)
 *
 * This enables any authenticated session with the user's privateKey
 * to discover the registry IPNS name without backend assistance.
 */

import { deriveKey, CryptoError, SECP256K1_PRIVATE_KEY_SIZE } from '@cipherbox/crypto';
import * as ed from '@noble/ed25519';
import { deriveIpnsName } from '../ipns/derive-name';

const REGISTRY_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
const REGISTRY_HKDF_INFO = new TextEncoder().encode('cipherbox-device-registry-ipns-v1');

/**
 * Derive the deterministic Ed25519 IPNS keypair for the device registry.
 *
 * Given the same secp256k1 privateKey, this always produces the same
 * IPNS name, enabling discovery from any device.
 *
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Ed25519 keypair and IPNS name for the registry
 * @throws CryptoError if the private key is not 32 bytes
 */
export async function deriveRegistryIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  // Validate input key length
  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
    throw new CryptoError('Invalid private key size for registry derivation', 'INVALID_KEY_SIZE');
  }

  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
  const ed25519Seed = await deriveKey({
    inputKey: userPrivateKey,
    salt: REGISTRY_HKDF_SALT,
    info: REGISTRY_HKDF_INFO,
    outputLength: 32,
  });

  // 2. Derive Ed25519 public key from seed (deterministic)
  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);

  // 3. Derive IPNS name from Ed25519 public key (k51... format)
  const ipnsName = await deriveIpnsName(ed25519PublicKey)

