# test-round-trip.ps1 -- Verify desktop FUSE writes are visible via the API (Windows).
#
# Usage: .\test-round-trip.ps1 [-MountPoint <path>] [-ApiUrl <url>]
#   -MountPoint   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   -ApiUrl       Backend API URL (default: http://localhost:3000)
#
# Environment:
#   TEST_SECRET   Shared secret for test-login (default: e2e-test-secret-ci-only)
#
# The server is zero-knowledge -- it cannot decrypt file contents.
# These tests prove the pipeline: FUSE write -> encrypt -> IPFS upload -> IPNS publish -> API visibility.
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox",
    [string]$ApiUrl = "http://localhost:3000"
)

$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$ErrorActionPreference = "Continue"

# Use the same email as the dev-key auth flow so we query the same user's vault
$TestEmail = "dev-key@cipherbox.local"
$RepoRoot = [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot "..\..\.."))
$TestFile = "rt-test-$PID-$(Get-Random).txt"
$TestContent = "API-visible content"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

function Ensure-VerifierRuntime {
    $sdkCoreDist = Join-Path $RepoRoot "packages/sdk-core/dist/index.mjs"
    $apiClientDist = Join-Path $RepoRoot "packages/api-client/dist/index.mjs"

    if ((Test-Path $sdkCoreDist) -and (Test-Path $apiClientDist)) {
        return
    }

    & pnpm --dir $RepoRoot --filter @cipherbox/crypto build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/crypto" }

    & pnpm --dir $RepoRoot --filter @cipherbox/core build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/core" }

    & pnpm --dir $RepoRoot --filter @cipherbox/api-client build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/api-client" }

    & pnpm --dir $RepoRoot --filter @cipherbox/sdk-core build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/sdk-core" }
}

Write-Host "=== API Round-Trip Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host "Test email:  $TestEmail"
Write-Host "Test file:   $TestFile"
Write-Host ""

Ensure-VerifierRuntime

function Invoke-FilePointerVerifier {
    $verifierPath = Join-Path $RepoRoot "packages/sdk-core/scripts/verify-filepointer.ts"
    $env:TEST_SECRET = $TestSecret
    $output = & pnpm exec tsx $verifierPath `
        --api-url $ApiUrl `
        --email $TestEmail `
        --file-name $TestFile `
        --expected-content $TestContent 2>&1 | Out-String

    return @($LASTEXITCODE, $output.Trim())
}

# ---- Test 1: Authenticate via test-login ----
Write-Host "--- Test 1: Authenticate via test-login ---"
$Body = @{
    email  = $TestEmail
    secret = $TestSecret
} | ConvertTo-Json

try {
    $AuthResponse = Invoke-RestMethod -Uri "$ApiUrl/auth/test-login" `
        -Method Post `
        -ContentType "application/json" `
        -Body $Body

    $AccessToken = $AuthResponse.accessToken
    if ($AccessToken) {
        Test-Pass "Authenticate via test-login"
    } else {
        Test-Fail "Authenticate via test-login (no accessToken in response)"
        Write-Host "FATAL: Cannot proceed without authentication."
        Write-Host ""
        Write-Host "=== API Round-Trip Results ==="
        Write-Host "  Passed: $Pass"
        Write-Host "  Failed: $Fail"
        Write-Host "==============================="
        exit $Fail
    }
} catch {
    Test-Fail "Authenticate via test-login ($_)"
    Write-Host "FATAL: Cannot proceed without authentication."
    Write-Host ""
    Write-Host "=== API Round-Trip Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "==============================="
    exit $Fail
}

$Headers = @{ Authorization = "Bearer $AccessToken" }

# ---- Test 2: Desktop writes file, API verifies vault exists ----
Write-Host "--- Test 2: Verify vault has content after FUSE write ---"
$FuseWriteSucceeded = $false
try {
    Set-Content -Path "$MountPoint\$TestFile" -Value $TestContent -NoNewline -ErrorAction Stop
    if (-not (Test-Path "$MountPoint\$TestFile")) { throw "FUSE write did not materialize at mount path" }
    $FuseWriteSucceeded = $true
    # Force a directory listing to drain upload completions — without this,
    # the background upload finishes but the publish queue never flushes
    # because no FUSE callbacks trigger drain_upload_completions() in CI.
    Start-Sleep -Seconds 2
    Get-ChildItem -Path $MountPoint -ErrorAction SilentlyContinue | Out-Null
} catch {
    Test-Fail "FUSE write failed ($_)"
}
if ($FuseWriteSucceeded) {
    $RootIpns = $null
    for ($attempt = 1; $attempt -le 24 -and -not $RootIpns; $attempt++) {
        Start-Sleep -Seconds 5
        try {
            $VaultResponse = Invoke-RestMethod -Uri "$ApiUrl/vault" -Headers $Headers
            $RootIpns = $VaultResponse.rootIpnsName
        } catch {
            Write-Host "  Vault poll attempt $attempt failed: $_"
        }
    }
    if ($RootIpns) {
        Test-Pass "Vault has rootIpnsName after FUSE write ($RootIpns)"
    } else {
        Test-Fail "Vault has no rootIpnsName after 120s polling"
    }
} else {
    Test-Fail "Vault verification skipped (FUSE write failed)"
    $RootIpns = $null
}

# ---- Test 3: Verify FilePointer and per-file IPNS metadata resolve ----
Write-Host "--- Test 3: Verify FilePointer and per-file IPNS metadata ---"
$VerifySucceeded = $false
$VerifyOutput = ""
for ($attempt = 1; $attempt -le 24 -and -not $VerifySucceeded; $attempt++) {
    Start-Sleep -Seconds 5
    $verifyResult = Invoke-FilePointerVerifier
    $verifyExit = [int]$verifyResult[0]
    $VerifyOutput = [string]$verifyResult[1]
    if ($verifyExit -eq 0) {
        $VerifySucceeded = $true
    } else {
        Write-Host "  FilePointer verify attempt $attempt failed: $VerifyOutput"
    }
}

if ($VerifySucceeded) {
    Test-Pass "FilePointer exists and per-file IPNS metadata resolves"
    Write-Host "  $VerifyOutput"
} else {
    Test-Fail "FilePointer/per-file IPNS verification failed after 120s"
}

# ---- Test 4: Verify fresh client reload can still resolve file metadata ----
Write-Host "--- Test 4: Verify fresh client reload resolves file metadata ---"
Start-Sleep -Seconds 2
$reloadResult = Invoke-FilePointerVerifier
$reloadExit = [int]$reloadResult[0]
$reloadOutput = [string]$reloadResult[1]
if ($reloadExit -eq 0) {
    Test-Pass "Fresh client reload resolves file metadata and content"
    Write-Host "  $reloadOutput"
} else {
    Test-Fail "Fresh client reload failed to resolve file metadata ($reloadOutput)"
}

# ---- Test 5: Verify IPNS resolve returns data ----
Write-Host "--- Test 5: Verify IPNS resolve returns CID ---"
if ($RootIpns) {
    $ResolvedCid = $null
    for ($attempt = 1; $attempt -le 24 -and -not $ResolvedCid; $attempt++) {
        Start-Sleep -Seconds 2
        try {
            $IpnsResponse = Invoke-RestMethod -Uri "$ApiUrl/ipns/resolve?ipnsName=$RootIpns" -Headers $Headers
            $ResolvedCid = if ($IpnsResponse.cid) { $IpnsResponse.cid } else { $IpnsResponse.value }
        } catch {
            Write-Host "  IPNS resolve attempt $attempt failed: $_"
        }
    }
    if ($ResolvedCid) {
        Test-Pass "IPNS resolve returned CID ($ResolvedCid)"
    } else {
        Test-Fail "IPNS resolve did not return expected CID after 48s polling"
    }
} else {
    Test-Fail "IPNS resolve skipped (no rootIpnsName)"
}

# ---- Cleanup ----
Write-Host "--- Cleanup ---"
Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2

# ---- Summary ----
Write-Host ""
Write-Host "=== API Round-Trip Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "==============================="

exit $Fail

# test-cross-client-sync.ps1 -- Verify FUSE mount picks up file edits made via SDK (Windows).
#
# Usage: .\test-cross-client-sync.ps1 [-MountPoint <path>] [-ApiUrl <url>]
#   -MountPoint   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   -ApiUrl       Backend API URL (default: http://localhost:3000)
#
# Environment:
#   TEST_SECRET   Shared secret for test-login (default: e2e-test-secret-ci-only)
#
# This test exercises the cross-client sync path:
# 1. Write a file via the FUSE mount (desktop client)
# 2. Edit the file via the SDK (simulating a web UI edit)
# 3. Wait for the FUSE mount to detect the change (IPNS polling)
# 4. Read the file from the FUSE mount and verify updated content
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox",
    [string]$ApiUrl = "http://localhost:3000"
)

$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$ErrorActionPreference = "Continue"

$TestEmail = "dev-key@cipherbox.local"
$RepoRoot = [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot "..\..\.."))
$TestFile = "sync-test-$(Get-Random).txt"
$OriginalContent = "Original content from FUSE mount"
$EditedContent = "Edited content from SDK client"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

function Ensure-SdkRuntime {
    $paths = @(
        "packages/sdk-core/dist/index.mjs",
        "packages/api-client/dist/index.mjs",
        "packages/core/dist/index.mjs",
        "packages/crypto/dist/index.mjs"
    )

    $allExist = $true
    foreach ($p in $paths) {
        if (-not (Test-Path (Join-Path $RepoRoot $p))) {
            $allExist = $false
            break
        }
    }

    if ($allExist) { return }

    Write-Host "Building SDK dependencies..."
    & pnpm --dir $RepoRoot --filter @cipherbox/crypto build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/crypto" }
    & pnpm --dir $RepoRoot --filter @cipherbox/core build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/core" }
    & pnpm --dir $RepoRoot --filter @cipherbox/api-client build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/api-client" }
    & pnpm --dir $RepoRoot --filter @cipherbox/sdk-core build
    if ($LASTEXITCODE -ne 0) { throw "Failed to build @cipherbox/sdk-core" }
}

function Invoke-SdkVerify {
    param([string]$ExpectedContent)
    $verifierPath = Join-Path $RepoRoot "packages/sdk-core/scripts/verify-filepointer.ts"
    $env:TEST_SECRET = $TestSecret
    $output = & pnpm exec tsx $verifierPath `
        --api-url $ApiUrl `
        --email $TestEmail `
        --file-name $TestFile `
        --expected-content $ExpectedContent 2>&1 | Out-String
    return @($LASTEXITCODE, $output.Trim())
}

function Invoke-SdkEdit {
    param([string]$NewContent)
    $editorPath = Join-Path $RepoRoot "packages/sdk-core/scripts/edit-filepointer.ts"
    $env:TEST_SECRET = $TestSecret
    $output = & pnpm exec tsx $editorPath `
        --api-url $ApiUrl `
        --email $TestEmail `
        --file-name $TestFile `
        --new-content $NewContent 2>&1 | Out-String
    return @($LASTEXITCODE, $output.Trim())
}

Write-Host "=== Cross-Client Sync Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host "Test email:  $TestEmail"
Write-Host "Test file:   $TestFile"
Write-Host ""

try {
    Ensure-SdkRuntime
} catch {
    Write-Host "FATAL: Failed to build SDK dependencies ($_)"
    exit 1
}

# ---- Test 1: Write file via FUSE mount ----
Write-Host "--- Test 1: Write file via FUSE mount ---"
try {
    Set-Content -Path "$MountPoint\$TestFile" -Value $OriginalContent -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 2
    # Trigger readdir to drain upload completions
    Get-ChildItem -Path $MountPoint -ErrorAction SilentlyContinue | Out-Null
} catch {
    Test-Fail "Write file via FUSE mount ($_)"
    Write-Host "FATAL: Cannot proceed without FUSE write."
    Write-Host ""
    Write-Host "=== Cross-Client Sync Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "=================================="
    exit $Fail
}

$FuseContent = $null
try { $FuseContent = (Get-Content -Path "$MountPoint\$TestFile" -Raw -ErrorAction Stop) } catch {}
if ($FuseContent -eq $OriginalContent) {
    Test-Pass "Write file via FUSE mount"
} else {
    Test-Fail "Write file via FUSE mount (got: '$FuseContent')"
}

# ---- Test 2: Wait for file to be visible via SDK ----
Write-Host "--- Test 2: Wait for file to be visible via SDK ---"
$SdkVerifyOk = $false
$VerifyOutput = ""
for ($attempt = 1; $attempt -le 24 -and -not $SdkVerifyOk; $attempt++) {
    # Trigger readdir each iteration to drain upload completions
    try { Get-Item "$MountPoint\$TestFile" -ErrorAction SilentlyContinue | Out-Null } catch {}
    Get-ChildItem -Path $MountPoint -ErrorAction SilentlyContinue | Out-Null
    Start-Sleep -Seconds 5
    $result = Invoke-SdkVerify -ExpectedContent $OriginalContent
    $exitCode = [int]$result[0]
    $VerifyOutput = [string]$result[1]
    if ($exitCode -eq 0) {
        $SdkVerifyOk = $true
    } else {
        Write-Host "  SDK verify attempt ${attempt}: $VerifyOutput"
    }
}

if ($SdkVerifyOk) {
    Test-Pass "File visible and decryptable via SDK"
    Write-Host "  $VerifyOutput"
} else {
    Test-Fail "File not visible via SDK after 120s"
    Write-Host "FATAL: Cannot proceed without SDK-visible file."
    Write-Host ""
    Write-Host "=== Cross-Client Sync Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "=================================="
    try { Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction SilentlyContinue } catch {}
    exit $Fail
}

# ---- Test 3: Edit file via SDK ----
Write-Host "--- Test 3: Edit file via SDK ---"
$editResult = Invoke-SdkEdit -NewContent $EditedContent
$editExit = [int]$editResult[0]
$editOutput = [string]$editResult[1]
if ($editExit -eq 0) {
    Test-Pass "Edit file via SDK"
    Write-Host "  $editOutput"
} else {
    Test-Fail "Edit file via SDK ($editOutput)"
    Write-Host "FATAL: Cannot test sync without successful edit."
    Write-Host ""
    Write-Host "=== Cross-Client Sync Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "=================================="
    try { Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction SilentlyContinue } catch {}
    exit $Fail
}

# ---- Test 4: Verify edit persisted via SDK ----
Write-Host "--- Test 4: Verify edit persisted via SDK ---"
Start-Sleep -Seconds 2
$verifyEditResult = Invoke-SdkVerify -ExpectedContent $EditedContent
$verifyEditExit = [int]$verifyEditResult[0]
$verifyEditOutput = [string]$verifyEditResult[1]
if ($verifyEditExit -eq 0) {
    Test-Pass "Edited content verified via SDK"
    Write-Host "  $verifyEditOutput"
} else {
    Test-Fail "Edited content not verified via SDK ($verifyEditOutput)"
}

# ---- Test 5: Wait for FUSE mount to pick up edited content ----
Write-Host "--- Test 5: Wait for FUSE mount to detect edit ---"
# The FUSE mount polls folder metadata every 30s. After detecting a newer
# modified_at on the FilePointer, it re-resolves the file's IPNS record
# to pick up the new CID. Allow up to 120s for two full polling cycles.
# IMPORTANT: Get-ChildItem triggers readdir which is a reliable operation
# for calling drain_refresh_completions() -> populate_folder().
$SyncOk = $false
for ($attempt = 1; $attempt -le 24 -and -not $SyncOk; $attempt++) {
    Start-Sleep -Seconds 5
    # Trigger readdir to drain refresh completions and detect modified_at changes
    Get-ChildItem -Path $MountPoint -ErrorAction SilentlyContinue | Out-Null
    $FuseContent = $null
    try { $FuseContent = (Get-Content -Path "$MountPoint\$TestFile" -Raw -ErrorAction Stop) } catch {}
    if ($FuseContent -eq $EditedContent) {
        $SyncOk = $true
        Write-Host "  Sync detected on attempt $attempt ($($attempt * 5)s)"
    } else {
        Write-Host "  Sync poll attempt ${attempt}: content still original"
    }
}

if ($SyncOk) {
    Test-Pass "FUSE mount picked up edited content"
} else {
    Test-Fail "FUSE mount still shows original content after 120s (got: '$FuseContent')"
}

# ---- Cleanup ----
Write-Host "--- Cleanup ---"
try { Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction SilentlyContinue } catch {}
Start-Sleep -Seconds 2

# ---- Summary ----
Write-Host ""
Write-Host "=== Cross-Client Sync Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "=================================="

exit $Fail

